/** Projection of a record to its UnitItem (contract I2) shape. */
export function toUnitItem(record: SubjectItem): UnitItem {
  return {
    id: record.id,
    group: record.group,
    objective: record.objective,
    standard:
      record.standard === "UNVERIFIED"
        ? "UNVERIFIED"
        : { code: record.standard.code, source: record.standard.source },
    why: record.why,
    buildsOn: [...record.buildsOn],
    useElsewhere: [...record.useElsewhere],
  };
}

/** Projection of a record's answer to the shared answer shape. */
export function toAnswerEntry(record: SubjectItem): SubjectAnswer {
  return projectAnswer(record.answer);
}

function projectAnswer(answer: SubjectAnswer): SubjectAnswer {
  const out: SubjectAnswer = {
    prompt: answer.prompt,
    choices: [...answer.choices],
    correct: answer.correct,
    derivation: answer.derivation,
  };
  if (answer.value !== undefined) out.value = answer.value;
  if (answer.kind !== undefined) out.kind = answer.kind;
  if (answer.followUp !== undefined) out.followUp = projectAnswer(answer.followUp);
  return out;
}

/** The live units for the subject module (contract I1 `units`). */
export function socialStudiesUnits(): UnitItem[] {
  return SOCIAL_STUDIES_RECORDS.map(toUnitItem);
}

/** Live items for one age band, in deal order. */
export function itemsForGroup(group: AgeGroup): UnitItem[] {
  return socialStudiesUnits().filter((item) => item.group === group);
}

/**
 * The curated rows stay JSON-backed: docs/scaling/social-studies/items.json
 * holds 23 rows and the 11 rows outside the live slice are not records
 * yet, so allSocialStudiesRows() keeps reading the data file (which this
 * module never edits).
 */
type RawRow = {
  id: string;
  group: AgeGroup;
  objective: string;
  standard: { code: string; source: string } | "UNVERIFIED";
  why: string;
  buildsOn: string[];
  useElsewhere: string[];
};

function isRawRow(value: unknown): value is RawRow {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const row = value as Record<string, unknown>;
  return (
    typeof row.id === "string" &&
    (row.group === "7-10" || row.group === "10-18" || row.group === "18+") &&
    typeof row.objective === "string" &&
    typeof row.why === "string" &&
    Array.isArray(row.buildsOn) &&
    Array.isArray(row.useElsewhere)
  );
}

/** Every curated social-studies row, in file order. */
export function allSocialStudiesRows(): UnitItem[] {
  const out: UnitItem[] = [];
  for (const raw of rows) {
    if (!isRawRow(raw)) continue;
    out.push({
      id: raw.id,
      group: raw.group,
      objective: raw.objective,
      standard: raw.standard,
      why: raw.why,
      buildsOn: [...raw.buildsOn],
      useElsewhere: [...raw.useElsewhere],
    });
  }
  return out;
}
